<?php
require __DIR__.'/../app/bootstrap.php'; require __DIR__.'/../app/layout.php'; require_permission('view_stock');
$q=trim($_GET['q']??'');$role=current_user()['role']??'';$showSellRates=in_array($role,['super_admin','manager','cashier'],true);$showReserved=in_array($role,['super_admin','manager','godown','auditor'],true);$isAdmin=is_super_admin();[$scope,$params]=location_scope_sql('ib.location_id');
$select='SELECT ib.qty physical_qty,ib.reserved_qty,GREATEST(ib.qty-ib.reserved_qty,0) sellable_qty,p.id product_id,p.sku,p.product_name,p.product_image,p.color,p.size,p.serial_tracking,b.id batch_id,b.batch_no,b.batch_barcode,b.purchased_at,l.code location_code,l.name location_name,l.warehouse,l.rack,l.shelf_bin';if($showSellRates)$select.=',p.retail_price,p.wholesale_price';if($isAdmin)$select.=',p.cost_code,b.cost_price batch_cost,b.cost_code batch_cost_code,s.party_name';$sql=$select.' FROM inventory_balances ib JOIN products p ON p.id=ib.product_id JOIN batches b ON b.id=ib.batch_id JOIN locations l ON l.id=ib.location_id';if($isAdmin)$sql.=' JOIN suppliers s ON s.id=b.supplier_id';$sql.=$role==='cashier'?' WHERE (ib.qty-ib.reserved_qty)>0':' WHERE ib.qty>0';$sql.=$scope;
if($q!==''){$sql.=" AND (p.sku LIKE ? OR p.product_name LIKE ? OR b.batch_barcode LIKE ? OR b.batch_no LIKE ? OR l.code LIKE ? OR EXISTS(SELECT 1 FROM product_serials ps WHERE ps.batch_id=b.id AND ps.location_id=ib.location_id AND ps.status IN ('AVAILABLE','RESERVED') AND ps.serial_barcode LIKE ?))";$like='%'.$q.'%';$params=array_merge($params,[$like,$like,$like,$like,$like,$like]);}$sql.=' ORDER BY p.product_name,b.purchased_at,l.code LIMIT 1000';$st=db()->prepare($sql);$st->execute($params);$rows=$st->fetchAll();page_header('Live Stock Inventory');?>
<form class="actions no-print" method="get"><input name="q" value="<?=e($q)?>" placeholder="Scan/search unique barcode, batch, SKU, product, rack/bin" data-scanner><button class="btn">Search</button></form><br><table><tr><th>Photo</th><th>Product</th><th>Tracking</th><th>Batch</th><th>Rack / Bin</th><?php if($showReserved):?><th>Physical</th><th>Reserved</th><?php endif;?><th>Sellable</th><?php if($showSellRates):?><th>Retail</th><th>Wholesale</th><?php endif;?><?php if($isAdmin):?><th>Party</th><th>Batch Cost</th><th>Cost Code</th><?php endif;?></tr>
<?php foreach($rows as $r):?><tr><td><?php if($r['product_image']):?><img src="<?=e($r['product_image'])?>" alt="" style="width:56px;height:56px;object-fit:cover;border-radius:8px"><?php endif;?></td><td><?=e($r['sku'].' · '.$r['product_name'])?><div class="muted"><?=e(trim($r['color'].' / '.$r['size'],' /'))?></div></td><td><?=$r['serial_tracking']?'<span class="badge">UNIQUE</span>':'<span class="badge">BATCH</span>'?></td><td><?=e($r['batch_no'])?><div class="muted"><?=e($r['batch_barcode'])?></div></td><td><b><?=e($r['location_code'])?></b><div class="muted"><?=e($r['warehouse'].' · Rack '.$r['rack'].' / Bin '.$r['shelf_bin'])?></div></td><?php if($showReserved):?><td><?=e($r['physical_qty'])?></td><td><?=e($r['reserved_qty'])?></td><?php endif;?><td class="qty-good"><?=e($r['sellable_qty'])?></td><?php if($showSellRates):?><td>₹<?=e(number_format($r['retail_price'],2))?></td><td>₹<?=e(number_format($r['wholesale_price'],2))?></td><?php endif;?><?php if($isAdmin):?><td><?=e($r['party_name'])?></td><td>₹<?=e(number_format($r['batch_cost'],2))?></td><td><?=e($r['batch_cost_code']?:$r['cost_code'])?></td><?php endif;?></tr><?php endforeach;?></table><?php page_footer();
